"""G1 humanoid action schema (engineering spec §9.3) — the REAL vocabulary.

Grounded in OM1's source (plugins/actions/unitree/g1/arm/zenoh.go, emotion, speak):
tool calls `speak`/`emotion`/`robot_action`, each with an {"action": "<value>"}
argument; the physical output is a discrete gesture on `api/sport/request`.
"""

import struct

from plumbline.adapters.base import Action
from plumbline.adapters.g1 import G1_GESTURES, G1ActionSchema, decode_sport_request
from plumbline.core.trace import JSONValue, Payload


def _tool_response(*calls: tuple[str, str]) -> Payload:
    return Payload(
        inline={
            "choices": [
                {
                    "message": {
                        "tool_calls": [
                            {
                                "id": f"t{i}",
                                "type": "function",
                                "function": {
                                    "name": name,
                                    "arguments": f'{{"action": "{value}"}}',
                                },
                            }
                            for i, (name, value) in enumerate(calls)
                        ]
                    }
                }
            ]
        }
    )


def test_command_vocabulary_is_the_real_tool_call_set() -> None:
    assert G1ActionSchema().commands == ("speak", "emotion", "robot_action")


def test_parse_real_tool_calls() -> None:
    plan = G1ActionSchema().parse(
        _tool_response(("robot_action", "shake_hand"), ("emotion", "happy"), ("speak", "hello!"))
    )
    assert plan == (
        Action("skill", "shake_hand", {}),
        Action("express", "happy", {}),
        Action("speak", "speak", {"text": "hello!"}),
    )


def test_parse_tolerates_unknown_and_malformed() -> None:
    assert G1ActionSchema().parse(_tool_response(("unknown_tool", "x"))) == ()
    assert G1ActionSchema().parse(Payload(inline={"other": 1})) == ()


def test_gesture_vocabulary_matches_om1_enum() -> None:
    # arm/zenoh.go ArmAction.EnumValues (idle is a connector no-op).
    assert "shake_hand" in G1_GESTURES and "talking_20s" in G1_GESTURES and "idle" in G1_GESTURES
    assert "walk" not in G1_GESTURES  # the G1 config has no locomotion action


def _sport_request(api_id: int, parameter: str) -> bytes:
    # Mirror of arm/zenoh.go serializeUnitreeRequest.
    param = parameter.encode() + b"\x00"
    buf = bytearray(b"\x00\x01\x00\x00")
    buf += struct.pack("<q", 0)  # identity.id
    buf += struct.pack("<q", api_id)  # identity.api_id
    buf += struct.pack("<q", 0)  # lease.id
    buf += struct.pack("<I", 0)  # policy.priority
    buf += b"\x00"  # policy.noreply
    buf += b"\x00\x00\x00"  # pad to data offset 32
    buf += struct.pack("<I", len(param)) + param
    data_len = len(buf) - 4
    buf += b"\x00" * ((4 - data_len % 4) % 4)
    buf += struct.pack("<I", 0)  # binary sequence length
    return bytes(buf)


def test_decode_sport_request_wire_layout() -> None:
    raw = _sport_request(9001, '{"action": "salute"}')
    decoded: JSONValue = decode_sport_request(raw)
    assert decoded == {"unitree_api/Request": {"api_id": 9001, "parameter": {"action": "salute"}}}
    assert decode_sport_request(b"\x00\x01\x00\x00short") is None
    assert decode_sport_request(b"\xff" + raw[1:]) is None  # wrong header

"""Grafana dashboards parse and reference only fields the feeds actually emit (§11).

The last test is the honesty guard: a dashboard selector naming a field the feed
builders don't produce fails CI, so the dashboards can't drift into referencing
attributes the code never emits.
"""

import json
from pathlib import Path
from typing import Any

from plumbline.core.seam import Seam
from plumbline.core.trace import Episode, JSONValue, Payload, SeamEvent, canonicalize
from plumbline.observability.baselines import BaselineComparison, MonitorVerdict
from plumbline.observability.feed import baseline_feed, episode_telemetry, gate_feed
from plumbline.regression.gating import EpisodeDrift, FailurePolicy, GateResult

_GRAFANA_DIR = Path(__file__).resolve().parent.parent / "plumbline" / "observability" / "grafana"


def _all_keys(obj: JSONValue) -> set[str]:
    keys: set[str] = set()
    if isinstance(obj, dict):
        for key, value in obj.items():
            keys.add(key)
            keys |= _all_keys(value)
    elif isinstance(obj, list):
        for item in obj:
            keys |= _all_keys(item)
    return keys


# Which feed(s) each dashboard binds to — its selectors are checked against ONLY
# these, so a telemetry panel cannot reference a gate-only field (or vice versa).
_DASHBOARD_FEEDS = {
    "plumbline-telemetry.json": ("telemetry",),
    "plumbline-regression.json": ("gate", "baseline"),
}


def _feed_keys() -> dict[str, set[str]]:
    request = Payload(inline={"m": 0})

    def event(seq: int, seam: Seam, response: JSONValue) -> SeamEvent:
        return SeamEvent(
            "ep",
            seq,
            seam,
            0,
            0.0,
            request,
            Payload(inline=response),
            "openai/gpt-4o",
            {},
            canonicalize(request).digest,
            1.0,
        )

    episode = Episode(
        "ep",
        (
            event(
                0, Seam.SENSOR_TO_CAPTION, {"usage": {"prompt_tokens": 1, "completion_tokens": 1}}
            ),
            event(1, Seam.FUSE_TO_DECIDE, {"choices": [{"message": {"content": "x"}}]}),
        ),
        {},
    )
    gate_result = GateResult(
        passed=False,
        threshold=0.1,
        policy=FailurePolicy.ANY,
        per_episode=(
            EpisodeDrift(
                "e1",
                drift=0.5,
                diverged=True,
                divergence_seam=Seam.CAPTION_TO_FUSE,
                divergence_distance=0.3,
            ),
        ),
    )
    comparison = BaselineComparison(verdicts=(MonitorVerdict("plumbline-behavior", False, "d"),))
    return {
        "telemetry": _all_keys(episode_telemetry(episode)),
        "gate": _all_keys(gate_feed(gate_result)),
        "baseline": _all_keys(baseline_feed(comparison)),
    }


def _selectors(obj: JSONValue) -> list[str]:
    found: list[str] = []
    if isinstance(obj, dict):
        for key, value in obj.items():
            if key in ("selector", "root_selector") and isinstance(value, str):
                found.append(value)
            else:
                found.extend(_selectors(value))
    elif isinstance(obj, list):
        for item in obj:
            found.extend(_selectors(item))
    return found


def _dashboards() -> list[Path]:
    return sorted(_GRAFANA_DIR.glob("*.json"))


def test_dashboards_present() -> None:
    assert _dashboards()


def test_dashboards_parse_and_have_structure() -> None:
    for path in _dashboards():
        dashboard: Any = json.loads(path.read_text(encoding="utf-8"))
        assert dashboard["title"]
        assert isinstance(dashboard["panels"], list) and dashboard["panels"]
        var_types = {var["type"] for var in dashboard["templating"]["list"]}
        assert "datasource" in var_types  # templated datasource, not a hardcoded UID


def test_dashboards_reference_only_real_feed_fields() -> None:
    feed_keys = _feed_keys()
    for path in _dashboards():
        assert path.name in _DASHBOARD_FEEDS, f"{path.name}: add it to _DASHBOARD_FEEDS"
        allowed: set[str] = set()
        for feed_name in _DASHBOARD_FEEDS[path.name]:
            allowed |= feed_keys[feed_name]
        dashboard: JSONValue = json.loads(path.read_text(encoding="utf-8"))
        for selector in _selectors(dashboard):
            # Validate EVERY path segment against ONLY the feed(s) this dashboard binds
            # to — a wrong parent path or a cross-feed field name fails CI.
            for segment in selector.split("."):
                assert segment in allowed, (
                    f"{path.name}: selector {selector!r} references {segment!r}, not a feed field"
                )

"""ActionSchema-derived behavior matcher (engineering spec §9.1, §14.6).

The gate scores behavioral drift by comparing DECIDE_TO_ACT action-plan payloads
with a `Matcher`. The exact / embedding / tolerance matchers work on raw JSON; this
one works on TYPED actions: it parses both payloads via an `ActionSchema` and
compares the resulting `Action` tuples position-by-position — same kind and name,
numeric args within tolerance — so `move(x=0.30)` vs `move(x=0.301)` is a match
while a changed skill or a dropped action is not. It is §14.6's "ActionSchema-
derived matcher" open choice made concrete; inject it as `GateSpec.behavior_matcher`.

Structurally satisfies the frozen core `Matcher` protocol (`matches -> MatchVerdict`)
and lives in `adapters/` because it depends on the (non-frozen) `ActionSchema`
surface — `core/` is frozen and must not depend on the adapter layer.
"""

from dataclasses import dataclass

from plumbline.adapters.base import Action, ActionSchema
from plumbline.core.matcher import MatchVerdict, NumericToleranceMatcher
from plumbline.core.trace import Payload


@dataclass(frozen=True)
class ActionSchemaMatcher:
    """Compare two action-plan payloads as typed `Action`s, with per-arg numeric
    tolerance (§14.6). Delegates arg comparison to `NumericToleranceMatcher`, so it
    inherits tolerance for numeric args, exact compare for non-numeric args, and
    NaN handling — consistent with the existing tolerance semantics."""

    schema: ActionSchema
    rtol: float = 1e-3
    atol: float = 1e-3
    # order_sensitive=False compares plans as multisets, so a behaviorally-identical
    # reordering isn't drift (§14.6 open choice — some runtimes are order-dependent).
    order_sensitive: bool = True

    def matches(self, live: Payload, recorded: Payload) -> MatchVerdict:
        live_actions = self._parse(live)
        recorded_actions = self._parse(recorded)
        total = max(len(live_actions), len(recorded_actions))
        if total == 0:
            # Both plans empty -> match, consistent with structural_equivalence's
            # both-empty convention (§14.6 open; documented, not silently inverted).
            return MatchVerdict(is_match=True, distance=0.0, reason="both action plans empty")
        arg_matcher = NumericToleranceMatcher(rtol=self.rtol, atol=self.atol)
        if self.order_sensitive:
            paired = min(len(live_actions), len(recorded_actions))
            matched = sum(
                _action_equal(live_actions[i], recorded_actions[i], arg_matcher)
                for i in range(paired)
            )
        else:
            matched = _multiset_matched(live_actions, recorded_actions, arg_matcher)
        # (total - matched) / max length, bounded [0, 1] — the §8.3/§14.6 shape (a
        # dropped/added/changed action still counts; a reorder counts only when
        # order_sensitive).
        distance = (total - matched) / total
        return MatchVerdict(
            is_match=distance == 0.0,
            distance=distance,
            reason=f"{matched}/{total} actions matched (order_sensitive={self.order_sensitive})",
        )

    def _parse(self, payload: Payload) -> tuple[Action, ...]:
        try:
            return tuple(self.schema.parse(payload))
        except Exception:  # a third-party schema that raises -> treat as unparseable
            return ()


def recommended_behavior_matcher(
    schema: ActionSchema, *, rtol: float = 1e-3, atol: float = 1e-3
) -> ActionSchemaMatcher:
    """The recommended gate `behavior_matcher` (§14.6): typed, numeric-tolerant, and
    reorder-insensitive — so it doesn't cry wolf on jitter or benign reordering.
    ExactMatcher stays available; the matcher choice is a human decision, so this is a
    recommendation, not a silent default change."""
    return ActionSchemaMatcher(schema, rtol=rtol, atol=atol, order_sensitive=False)


def _multiset_matched(
    live: tuple[Action, ...], recorded: tuple[Action, ...], arg_matcher: NumericToleranceMatcher
) -> int:
    """Greedy multiset match: each live action consumes the first unused recorded
    action it equals. (Tolerance-equality isn't transitive, so this is conservative —
    same spirit as structural_equivalence's alignment.)"""
    remaining = list(recorded)
    matched = 0
    for action in live:
        for index, candidate in enumerate(remaining):
            if _action_equal(action, candidate, arg_matcher):
                del remaining[index]
                matched += 1
                break
    return matched


def _action_equal(live: Action, recorded: Action, arg_matcher: NumericToleranceMatcher) -> bool:
    if live.kind != recorded.kind or live.name != recorded.name:
        return False
    return arg_matcher.matches(
        Payload(inline=dict(live.args)), Payload(inline=dict(recorded.args))
    ).is_match

"""Offline check of the Modal validation driver (no network): proves the record ->
faithful-replay byte-identical logic with a fake transport, so the harness is
CI-verified even though the real run points at Modal."""

import asyncio
import json

import examples.modal_validate as mv
from plumbline.core.store import TraceStore
from plumbline.proxy.http import HTTPRequest, HTTPResponse
from plumbline.proxy.normalizers import contains_image


class _FakeTransport:
    async def send(self, request: HTTPRequest) -> HTTPResponse:
        body = json.loads(request.body)
        payload: dict[str, object]
        if contains_image(body):
            payload = {"choices": [{"message": {"content": "a clear corridor ahead"}}]}
        else:
            payload = {
                "choices": [
                    {
                        "message": {
                            "tool_calls": [
                                {
                                    "function": {
                                        "name": "Move",
                                        "arguments": '{"action": "move forwards"}',
                                    }
                                }
                            ]
                        }
                    }
                ]
            }
        return HTTPResponse(
            status=200,
            headers={"content-type": "application/json"},
            body=json.dumps(payload).encode(),
        )


def test_record_and_faithful_replay_byte_identical() -> None:
    store = TraceStore()
    episode_id = asyncio.run(
        mv.record_episode(
            _FakeTransport(), store, vlm_url="http://vlm", llm_url="http://llm", ticks=3
        )
    )
    events = store.load_episode(episode_id).events
    assert len(events) == 6  # 3 ticks x (vision + cortex)
    # The three identical vision requests share a digest; faithful replay serves them
    # in record order (the digest-occurrence fix) — byte-identical throughout.
    assert mv.verify_faithful_replay(store, episode_id) is True


def test_main_is_callable() -> None:
    assert callable(mv.main)
